import { useEffect, useMemo, useState } from 'react';

// ---- inlined from wfc ----
/**
 * Wave Function Collapse over a 16-tile pipe set. A tile id IS its edge bitmask
 * (bit 0 N, 1 E, 2 S, 3 W), and every edge combination exists as a tile, so any
 * arc-consistent domain is non-empty and the collapse never contradicts. The drama
 * is entropy draining outward from each collapse, not backtracking.
 */

const WFC_COLS = 30;
const WFC_ROWS = 18;
const CELLS = WFC_COLS * WFC_ROWS;
const SEED = 20260818;

/** mulberry32: a fixed seed keeps every collapse identical across reloads. */
function seededRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function popcount(x: number): number {
  let count = 0;
  let v = x;
  while (v) {
    v &= v - 1;
    ++count;
  }
  return count;
}

/** Sparse-circuit weights by pipe count: blank and 2-pipe tiles dominate, crosses are rare. */
const WEIGHT_BY_PIPES = [24, 3, 9, 2, 1];
const weight = (tile: number) => WEIGHT_BY_PIPES[popcount(tile)];

/** EDGE_MASK[dir][v]: the tiles whose edge bit in direction dir equals v. */
const EDGE_MASK = [0, 1, 2, 3].map((dir) =>
  [0, 1].map((v) => {
    let mask = 0;
    for (let t = 0; t < 16; ++t) if (((t >> dir) & 1) === v) mask |= 1 << t;
    return mask;
  })
);
const OPPOSITE = [2, 3, 0, 1];
const DX = [0, 1, 0, -1];
const DY = [-1, 0, 1, 0];

interface WfcStep {
  cell: number;
  tile: number;
  /** Remaining possibilities per cell after this collapse propagates; 0 once collapsed. */
  counts: Uint8Array;
}

function generateWfc(): WfcStep[] {
  const random = seededRandom(SEED);
  const domain = new Array<number>(CELLS).fill(0xffff);
  const collapsed = new Array<boolean>(CELLS).fill(false);
  const steps: WfcStep[] = [];

  const propagate = (from: number) => {
    const queue = [from];
    while (queue.length) {
      const i = queue.pop() as number;
      const col = i % WFC_COLS;
      const row = (i / WFC_COLS) | 0;
      for (let dir = 0; dir < 4; ++dir) {
        const nc = col + DX[dir];
        const nr = row + DY[dir];
        if (nc < 0 || nc >= WFC_COLS || nr < 0 || nr >= WFC_ROWS) continue;
        const j = nr * WFC_COLS + nc;
        let allowed = 0;
        for (const v of [0, 1]) {
          if (domain[i] & EDGE_MASK[dir][v]) allowed |= EDGE_MASK[OPPOSITE[dir]][v];
        }
        const next = domain[j] & allowed;
        if (next !== domain[j]) {
          domain[j] = next;
          queue.push(j);
        }
      }
    }
  };

  // Pipes stop at the boundary: border cells lose the tiles that run off the grid.
  for (let i = 0; i < CELLS; ++i) {
    const col = i % WFC_COLS;
    const row = (i / WFC_COLS) | 0;
    if (row === 0) domain[i] &= EDGE_MASK[0][0];
    if (col === WFC_COLS - 1) domain[i] &= EDGE_MASK[1][0];
    if (row === WFC_ROWS - 1) domain[i] &= EDGE_MASK[2][0];
    if (col === 0) domain[i] &= EDGE_MASK[3][0];
    propagate(i);
  }

  for (let n = 0; n < CELLS; ++n) {
    let bestCount = 17;
    let pool: number[] = [];
    for (let i = 0; i < CELLS; ++i) {
      if (collapsed[i]) continue;
      const count = popcount(domain[i]);
      if (count < bestCount) {
        bestCount = count;
        pool = [i];
      } else if (count === bestCount) {
        pool.push(i);
      }
    }
    const cell = pool[(random() * pool.length) | 0];

    let total = 0;
    for (let t = 0; t < 16; ++t) if (domain[cell] & (1 << t)) total += weight(t);
    let pick = random() * total;
    let tile = 0;
    for (let t = 0; t < 16; ++t) {
      if (!(domain[cell] & (1 << t))) continue;
      pick -= weight(t);
      tile = t;
      if (pick <= 0) break;
    }

    domain[cell] = 1 << tile;
    collapsed[cell] = true;
    propagate(cell);

    const counts = new Uint8Array(CELLS);
    for (let i = 0; i < CELLS; ++i) counts[i] = collapsed[i] ? 0 : popcount(domain[i]);
    steps.push({ cell, tile, counts });
  }

  return steps;
}

/** Pipe strokes for one collapsed cell: centre to each open edge's midpoint. */
function tilePath(cell: number, tile: number, size: number): string {
  if (!tile) return '';
  const cx = ((cell % WFC_COLS) + 0.5) * size;
  const cy = (((cell / WFC_COLS) | 0) + 0.5) * size;
  const edgeX = [cx, cx + size / 2, cx, cx - size / 2];
  const edgeY = [cy - size / 2, cy, cy + size / 2, cy];
  let d = '';
  for (let dir = 0; dir < 4; ++dir) {
    if (tile & (1 << dir)) {
      d += `M${edgeX[dir].toFixed(1)},${edgeY[dir].toFixed(1)}L${cx.toFixed(1)},${cy.toFixed(1)}`;
    }
  }
  return d;
}

function cellSquare(cell: number, size: number): string {
  const x = (cell % WFC_COLS) * size;
  const y = ((cell / WFC_COLS) | 0) * size;
  return `M${x.toFixed(1)},${y.toFixed(1)}h${size.toFixed(1)}v${size.toFixed(1)}h${(-size).toFixed(1)}Z`;
}

const TICK_MS = 45;
const TARGET_TICKS = 260;
const HOLD_TICKS = 40;
const HOT = '#e0538a';

/** Fewer remaining possibilities burn hotter; near-full domains stay invisible. */
const HEAT_BANDS = [
  { max: 1, opacity: 0.6 },
  { max: 3, opacity: 0.42 },
  { max: 6, opacity: 0.26 },
  { max: 10, opacity: 0.12 }
];

export default function WaveFunctionCollapse({ width }: { width: number }) {
  const cell = Math.max(1, width) / WFC_COLS;
  const gridHeight = Math.round(cell * WFC_ROWS);
  const height = gridHeight + 20;

  const steps = useMemo(() => generateWfc(), []);
  const fragments = useMemo(() => steps.map((s) => tilePath(s.cell, s.tile, cell)), [steps, cell]);

  // The SSR frame is the fully collapsed circuit; the effect rewinds and replays.
  const [step, setStep] = useState(steps.length);

  useEffect(() => {
    const perTick = Math.max(1, Math.ceil(steps.length / TARGET_TICKS));
    const end = steps.length + perTick * HOLD_TICKS;
    setStep(0);
    const id = window.setInterval(() => setStep((s) => (s >= end ? 0 : s + perTick)), TICK_MS);
    return () => window.clearInterval(id);
  }, [steps.length]);

  const shown = Math.min(step, steps.length);
  const pipes = useMemo(() => fragments.slice(0, shown).join(''), [fragments, shown]);

  const heat = useMemo(() => {
    if (shown === 0 || shown >= steps.length) return [];
    const counts = steps[shown - 1].counts;
    const byBand = HEAT_BANDS.map(() => [] as string[]);
    for (let i = 0; i < counts.length; ++i) {
      if (counts[i] === 0) continue;
      const band = HEAT_BANDS.findIndex(({ max }) => counts[i] <= max);
      if (band >= 0) byBand[band].push(cellSquare(i, cell));
    }
    return byBand.map((squares, b) => ({ opacity: HEAT_BANDS[b].opacity, d: squares.join('') }));
  }, [steps, shown, cell]);

  if (width === 0) return null;

  const latest = shown > 0 && shown < steps.length ? steps[shown - 1].cell : -1;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Wave function collapse assembling a pipe circuit: each tick the least-certain cell commits to a tile, constraints propagate, and the heat map shows certainty draining outward from every collapse until the whole grid is decided"
    >
      {heat.map(({ opacity, d }, b) => (
        <path key={b} d={d} fill={HOT} opacity={opacity} />
      ))}
      {latest >= 0 && <path d={cellSquare(latest, cell)} fill={HOT} opacity={0.85} />}
      <path
        d={pipes}
        fill="none"
        stroke="var(--accent)"
        strokeWidth={cell * 0.3}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      <text x={4} y={height - 6} fill="var(--muted)" fontSize={11}>
        {shown < steps.length ? `${shown} of ${steps.length} cells collapsed` : 'fully collapsed'}
      </text>
    </svg>
  );
}
